from collections import deque

def traverse(graph, start):
    seen, q, order = {start}, deque([start]), []
    while q:
        node = q.popleft()              # FIFO -> level by level
        order.append(node)
        for nb in graph[node]:
            if nb not in seen:
                seen.add(nb)
                q.append(nb)
    return order

def traverse(graph, node, seen=None):
    if seen is None:
        seen = set()
    seen.add(node)
    for nb in graph[node]:              # go as deep as possible
        if nb not in seen:
            traverse(graph, nb, seen)
    return seen

import heapq

def shortest(graph, src):              # weights >= 0
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)       # closest unsettled node
        for v, w in graph[u]:
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

def max_subarray(a):
    best = cur = a[0]
    for x in a[1:]:
        cur = max(x, cur + x)          # extend or restart
        best = max(best, cur)
    return best                        # O(n), O(1) space

def solve(weights, values, cap):
    n = len(weights)
    dp = [[0] * (cap + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(cap + 1):
            dp[i][w] = dp[i - 1][w]            # skip item i
            if weights[i - 1] <= w:            # or take it
                dp[i][w] = max(dp[i][w],
                    values[i - 1] + dp[i - 1][w - weights[i - 1]])
    return dp[n][cap]

def solve(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]
